
import { z } from "zod/v4";

/**
 * Resume structure schema.
 *
 * Version 1 preserves the original source text and separates it
 * from the normalized information generated by the AI.
 */

const nullableText = z.string().nullable();

const identifiedItem = z.object({
  id: z.string().min(1),
});

/**
 * Exact snapshot of the source fields in resume_profiles.
 * These values must never be rewritten by the AI.
 */
export const ResumeSourceSnapshotSchema = z.object({
  headline: nullableText,
  summary: nullableText,
  experience: nullableText,
  skills: nullableText,
  education: nullableText,
  certifications: nullableText,

  full_name: nullableText,
  phone: nullableText,
  email: nullableText,
  state: nullableText,
  country: nullableText,
  postal_code: nullableText,
  linkedin: nullableText,
  portfolio: nullableText,
});

/**
 * Contact information from resume_profiles.
 */
export const ResumeContactSchema = z.object({
  full_name: nullableText,
  phone: nullableText,
  email: nullableText,
  state: nullableText,
  country: nullableText,
  postal_code: nullableText,
  linkedin: nullableText,
  portfolio: nullableText,
});

/**
 * Professional title and summary.
 */
export const ResumeTextFieldSchema = z.object({
  original_text: nullableText,
  normalized_text: nullableText,
});

/**
 * Individual responsibility.
 *
 * original_text must match the source responsibility exactly.
 * normalized_text may contain an adapted or translated version.
 */
export const ResumeResponsibilitySchema = z.object({
  id: z.string().min(1),
  original_text: z.string().min(1),
  normalized_text: nullableText,
});

/**
 * Work experience.
 */
export const ResumeExperienceSchema = z.object({
  id: z.string().min(1),

  company: nullableText,
  position: nullableText,

  start_date: nullableText,
  end_date: nullableText,
  employment_status: z.enum(["current", "ended", "unknown"]),

  original_date_text: nullableText,
  original_text: nullableText,

  responsibilities: z.array(ResumeResponsibilitySchema),
});

/**
 * Technical skills.
 *
 * source_text preserves the exact text found in the original CV.
 * name may contain a normalized presentation of that skill.
 */
export const ResumeSkillSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  source_text: z.string().min(1),
});

/**
 * Education.
 */
export const ResumeEducationSchema = z.object({
  id: z.string().min(1),

  original_text: z.string().min(1),

  degree: nullableText,
  institution: nullableText,
  graduation_year: nullableText,
});

/**
 * Certifications.
 */
export const ResumeCertificationSchema = z.object({
  id: z.string().min(1),

  original_text: z.string().min(1),

  name: nullableText,
  issuer: nullableText,
  issue_date: nullableText,
  expiration_date: nullableText,
  credential_id: nullableText,
});

/**
 * Complete structured resume, version 1.
 */
export const ResumeStructureSchema = z
  .object({
    schema_version: z.literal(1),

    source_snapshot: ResumeSourceSnapshotSchema,

    contact: ResumeContactSchema,

    professional_title: ResumeTextFieldSchema,
    professional_summary: ResumeTextFieldSchema,

    experience: z.array(ResumeExperienceSchema),

    technical_skills: z.array(ResumeSkillSchema),

    education: z.array(ResumeEducationSchema),

    certifications: z.array(ResumeCertificationSchema),
  })
  .superRefine((resume, context) => {
    /**
     * IDs must be unique within each collection.
     */
    const validateUniqueIds = (
      ids: string[],
      path: (string | number)[],
    ) => {
      const seen = new Set<string>();

      ids.forEach((id, index) => {
        if (seen.has(id)) {
          context.addIssue({
            code: "custom",
            path: [...path, index, "id"],
            message: `Duplicate identifier: ${id}`,
          });
        }

        seen.add(id);
      });
    };

    validateUniqueIds(
      resume.experience.map((item) => item.id),
      ["experience"],
    );

    validateUniqueIds(
      resume.technical_skills.map((item) => item.id),
      ["technical_skills"],
    );

    validateUniqueIds(
      resume.education.map((item) => item.id),
      ["education"],
    );

    validateUniqueIds(
      resume.certifications.map((item) => item.id),
      ["certifications"],
    );

    /**
     * Responsibility IDs must be unique across all positions,
     * not just within an individual position.
     */
    const responsibilityIds = resume.experience.flatMap((position) =>
      position.responsibilities.map((responsibility) => responsibility.id),
    );

    const seenResponsibilityIds = new Set<string>();

    responsibilityIds.forEach((id, index) => {
      if (seenResponsibilityIds.has(id)) {
        context.addIssue({
          code: "custom",
          path: ["experience"],
          message: `Duplicate responsibility identifier: ${id}`,
        });
      }

      seenResponsibilityIds.add(id);
    });
  });

/**
 * TypeScript types inferred directly from the Zod schemas.
 */
export type ResumeSourceSnapshot = z.infer<
  typeof ResumeSourceSnapshotSchema
>;

export type ResumeContact = z.infer<
  typeof ResumeContactSchema
>;

export type ResumeResponsibility = z.infer<
  typeof ResumeResponsibilitySchema
>;

export type ResumeExperience = z.infer<
  typeof ResumeExperienceSchema
>;

export type ResumeSkill = z.infer<
  typeof ResumeSkillSchema
>;

export type ResumeEducation = z.infer<
  typeof ResumeEducationSchema
>;

export type ResumeCertification = z.infer<
  typeof ResumeCertificationSchema
>;

export type ResumeStructure = z.infer<
  typeof ResumeStructureSchema
>;
